head.script:
        	scwin.count = 0;
			scwin.onpageload = function() {			
			var bFormatter = function () {
			    return [
			        {
			            'id' : 'custombtn',
			            'className' : 'w2widget_btnCustom w2widget_btnCustom1',
			            'isCustom' : true,
						'isCustomDirection': 'left'
			        },
			        {
			            'id' : 'custombtn2',
						'isCustom' : true,
			            'className' : 'w2widget_btnCustom w2widget_btnCustom2'
			        },
			        {
			            'id' : 'custombtn3',
			            'className' : 'w2widget_btnCustom3',
			            'isCustom' : true,
						'isCustomDirection': 'left'
			        },
			        {'useDefault' : 'maximize'},
			        {'useDefault' : 'close'}
			    ];
			};

				scwin.count++;
				ui_wgc_main.addWidgets({
				    id : "widget"+scwin.count,
				    title : "위젯!!!"+scwin.count,
				    src : "girdview_textImage.xml",
				    scope : true,
				    x : 0,
				    y : 0,
				    unitWidth : 1,
				    unitHeight : 1,
					buttonFormatter : bFormatter
				});		
				scwin.count++;
				ui_wgc_main.addWidgets({
				    id : "widget"+scwin.count,
				    title : "위젯위젯~~~~~~"+scwin.count,
				    src : "girdview_textImage.xml",
				    scope : true,
				    x : 1,
				    y : 0,
				    unitWidth : 1,
				    unitHeight : 1
				});		
				scwin.count++;
				ui_wgc_main.addWidgets({
				    id : "widget"+scwin.count,
				    title : "위젯"+scwin.count,
				    src : "girdview_textImage.xml",
				    scope : true,
				    x : 2,
				    y : 0,
				    unitWidth : 1,
				    unitHeight : 1,
					buttonFormatter : bFormatter
				});



				scwin.count++;
				ui_wgc_main2.addWidgets({
				    id : "widget"+scwin.count,
				    title : "위젯"+scwin.count,
				    src : "girdview_textImage.xml",
				    scope : true,
				    x : 0,
				    y : 0,
				    unitWidth : 1,
				    unitHeight : 1,
					buttonFormatter : bFormatter
				});		
				scwin.count++;
				ui_wgc_main2.addWidgets({
				    id : "widget"+scwin.count,
				    title : "위젯"+scwin.count,
				    src : "girdview_textImage.xml",
				    scope : true,
				    x : 1,
				    y : 0,
				    unitWidth : 1,
				    unitHeight : 1
				});		
				scwin.count++;
				ui_wgc_main2.addWidgets({
				    id : "widget"+scwin.count,
				    title : "위젯"+scwin.count,
				    src : "girdview_textImage.xml",
				    scope : true,
				    x : 2,
				    y : 0,
				    unitWidth : 1,
				    unitHeight : 1,
					buttonFormatter : bFormatter
				});
			};
			scwin.onpageunload = function() {

			};
			scwin.widgetContainer_onclickcustombtn = function(widgetId,btnId) {
		alert("위젯아이디 : "+widgetId+"\n"+"버튼아이디 : "+btnId);
	};

	scwin.checkVal = function(id) {
		let check_tagName1 = WebSquare.wUnit.getDomById(id).previousElementSibling.tagName;
		let check_tagName2 = WebSquare.wUnit.getDomById(id).nextElementSibling.tagName;

		return check_tagName1 == 'STRONG' && check_tagName2 == 'BUTTON';
	}	
	scwin.checkVal2 = function(id) {
		let check_tagName1 = WebSquare.wUnit.getDomById(id).previousElementSibling;
		let check_tagName2 = WebSquare.wUnit.getDomById(id).nextElementSibling.tagName;

		return check_tagName1 === null && check_tagName2 == 'BUTTON';
	}		
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal('ui_wgc_main_widget1_title_custombtn')", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal('ui_wgc_main_widget3_title_custombtn')", "true");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2('ui_wgc_main_widget1_title_custombtn2')", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2('ui_wgc_main_widget3_title_custombtn2')", "true");
		WebSquare.wUnit.addCommand("pause", "500");				
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest();
